# Contexto neutral por pregunta, en lenguaje llano. Se guarda en docs/taxonomy/question_context.json
import json, sys
C = {
"Q001": "Las becas ayudan a pagar la matrícula, la residencia o los gastos de quien estudia con pocos recursos. Unos quieren darles más dinero para que el nivel de renta no decida quién estudia. Otros prefieren gastar en otras cosas o ligar las ayudas al rendimiento.",
"Q002": "La educación de 0 a 3 años no es obligatoria. Hay escuelas públicas, concertadas y privadas, y en algunos sitios faltan plazas públicas. Unos piden más plazas públicas y baratas. Otros prefieren ayudar a las familias a pagar una plaza privada.",
"Q003": "La vivienda protegida tiene el precio limitado y se destina a hogares con ingresos bajos o medios. Unos quieren que el Estado construya más para aumentar la oferta asequible. Otros confían más en que construya el sector privado, con más suelo y menos trabas.",
"Q004": "Una zona tensionada es un área donde el alquiler se come buena parte del sueldo. Desde la Ley de Vivienda de 2023, las comunidades pueden declararlas y frenar las subidas. Unos defienden regular los precios. Otros creen que topar el alquiler hace que haya menos pisos y suba más.",
"Q005": "Hablamos del IBI, la plusvalía municipal o el impuesto que se paga al comprar una casa. Unos quieren cambiarlos para facilitar el acceso a la vivienda, bajándolos o gravando más a quien acumula pisos. Otros prefieren dejarlos como están porque financian a los ayuntamientos.",
"Q006": "La sanidad pública depende sobre todo de las comunidades. Las listas de espera y la saturación del médico de cabecera son quejas habituales. Unos piden más dinero para la sanidad pública. Otros prefieren contener el gasto, mejorar la gestión o dar más papel al sector privado.",
"Q007": "Rehabilitar es reformar los edificios y barrios que ya existen, en vez de construir zonas nuevas en las afueras. Unos quieren darle prioridad. Otros piensan que también hace falta más suelo urbanizable para aumentar la oferta rápido.",
"Q008": "Se trata de proteger al inquilino con medidas como prorrogar contratos, limitar los desahucios o frenar las subidas de renta. Unos quieren reforzar esa protección. Otros temen que, si se protege demasiado, los propietarios dejen de alquilar.",
"Q009": "Las grandes fortunas pagan el impuesto sobre el patrimonio, y las empresas, el de sociedades. Algunos partidos piden subirlos o crear gravámenes especiales para financiar los servicios públicos. Otros temen que eso espante la inversión o que el capital se vaya fuera.",
"Q010": "El IRPF es el impuesto sobre la renta de las personas y sube por tramos según lo que se gana. Unos quieren bajarlo a las clases medias y trabajadoras para que les quede más dinero. Otros creen que se recaudaría menos para servicios públicos.",
"Q011": "Hablamos de trenes. Por un lado, el AVE. Por otro, las cercanías y la media distancia, que conectan ciudades y pueblos. Unos piden invertir más para unir mejor los territorios. Otros prefieren cuidar lo que ya hay o gastar en otras cosas.",
"Q012": "Las deducciones rebajan lo que pagan en el IRPF las familias con hijos. Unos quieren ampliarlas para apoyar la crianza y la natalidad. Otros prefieren ayudas directas o piensan que cuestan demasiado.",
"Q013": "Los incendios forestales han ido a más en los últimos años. Prevenirlos exige limpiar el monte, mantener brigadas y apoyar a los pueblos. Unos piden más medios y más protección. Otros creen que lo actual basta o prefieren gastar el dinero en otra cosa.",
"Q014": "La ayuda al desarrollo es el dinero público que un país dedica a cooperar con países más pobres. La ONU propone destinar el 0,7 % de la renta nacional, y España está por debajo. Unos quieren llegar a esa cifra. Otros prefieren gastar ese dinero en necesidades de dentro.",
"Q015": "Digitalizar es poder hacer por internet los trámites con la administración, como los impuestos, las citas o los certificados. Unos quieren impulsarlo para ganar rapidez. Otros avisan de que quien no maneja lo digital se queda atrás y piden mantener siempre la opción presencial.",
"Q016": "Una política industrial activa significa que el Estado ayuda a sectores clave, como los chips, las baterías o el automóvil, con dinero, inversión o incentivos. Unos creen que debe liderar para atraer empresas y empleo. Otros prefieren dejar actuar al mercado y bajar impuestos.",
"Q017": "La rehabilitación energética es mejorar el aislamiento, las ventanas o la calefacción de los edificios para gastar menos energía. Unos quieren subvenciones o deducciones para animar a hacerla. Otros dicen que es un coste del propietario o dudan de que funcione.",
"Q018": "El mecenazgo son ventajas fiscales para quien financia cultura. Los derechos de autor protegen a creadores y editores. Unos quieren reformar estas leyes para apoyar a artistas y a la industria cultural. Otros creen que la regulación actual vale o prefieren menos ayudas públicas.",
"Q019": "La cuestión es si España, al elegir con quién se relaciona, debe poner por delante los derechos humanos y la democracia aunque eso cueste dinero o fricciones diplomáticas. Unos dicen que sí. Otros piensan que deben pesar más los intereses del país, la seguridad o la economía.",
"Q020": "El patrimonio cultural son los monumentos, los museos, los archivos y las tradiciones. Unos piden más inversión pública para conservarlo y darle uso. Otros prefieren dedicar el dinero a otras cosas o contar más con la inversión privada.",
"Q022": "Participación directa quiere decir que la gente decide sin pasar por sus representantes. Por ejemplo, con un referéndum o con una iniciativa popular, en la que se propone una ley reuniendo firmas. Unos quieren ampliarla. Otros creen que deben decidir sobre todo los parlamentos, porque los asuntos son complejos.",
"Q023": "Hablamos del dinero para policía, Guardia Civil y medios de seguridad, como personal, tecnología y equipamiento. Unos quieren aumentarlo para reforzar la seguridad en la calle. Otros prefieren invertir en prevención social o en otros servicios.",
"Q024": "En España viven personas sin permiso de residencia. Una regularización extraordinaria les daría papeles a todas a la vez, como pedía la iniciativa popular que se tramitó hace poco. Unos dicen que así podrían trabajar y cotizar con derechos. Otros temen un efecto llamada y prefieren estudiar cada caso.",
"Q025": "Son personas que piden protección porque huyen de una guerra o de una persecución. España estudia cada solicitud y la UE tiene normas comunes, el Pacto de Migración y Asilo. Unos quieren acoger a más gente. Otros prefieren mantener o reducir la acogida por capacidad, seguridad o coste.",
"Q026": "Se trata de vigilar más las fronteras y de devolver a su país a quien entra sin autorización. Unos piden reforzar el control y agilizar las devoluciones. Otros avisan de que se pueden vulnerar derechos humanos y prefieren vías legales y seguras.",
"Q027": "En 2019 se acordó un calendario para ir cerrando las centrales nucleares españolas entre 2027 y 2035. Unos quieren mantenerlas abiertas más tiempo porque dan energía estable y sin emisiones. Otros prefieren cerrarlas según lo previsto, por la seguridad, los residuos o la apuesta por las renovables.",
"Q028": "Las energías renovables, como la solar y la eólica, van sustituyendo al gas y al petróleo. Unos quieren acelerar con más inversión y menos trabas. Otros prefieren ir más despacio por el coste, la estabilidad del suministro o el impacto en el paisaje.",
"Q029": "España funciona con comunidades autónomas que se reparten competencias con el Estado. Unos quieren que el Estado transfiera más competencias a las comunidades. Otros creen que ya se ha transferido bastante o incluso piden centralizar más.",
"Q030": "Esta es la pregunta contraria a la anterior. Hoy las comunidades gestionan la educación y la sanidad. Unos quieren que el Estado las recupere para que haya más igualdad entre territorios. Otros prefieren que sigan en manos autonómicas por cercanía y autogobierno.",
"Q031": "La jornada máxima legal es hoy de 40 horas a la semana. Unos quieren reducirla, por ejemplo a 37,5 o a 32 horas, sin bajar el sueldo, para tener más tiempo libre y más productividad. Otros temen el coste para las empresas, sobre todo las pequeñas, o prefieren pactarlo en cada sector.",
"Q032": "El salario mínimo es el sueldo más bajo que se puede pagar por ley, y el Gobierno lo fija cada año. Unos quieren subirlo por encima del nivel actual para mejorar los sueldos más bajos. Otros temen que así se destruya empleo o se perjudique a las empresas pequeñas.",
"Q033": "La normativa de contratación y despido marca los tipos de contrato, las causas de despido y las indemnizaciones. Unos quieren hacerla más flexible para que sea más fácil contratar y despedir. Otros defienden mantener o reforzar la estabilidad y la protección de quien trabaja.",
"Q034": "La escuela concertada la gestionan entidades privadas, pero se paga con dinero público. Unos quieren dar prioridad a la escuela pública en la financiación. Otros defienden apoyar también a la concertada y la libertad de las familias para elegir centro.",
"Q035": "Hoy la Formación Profesional y la matrícula universitaria tienen precios distintos según la titulación y la comunidad. Unos quieren ampliar la gratuidad para quitar barreras económicas. Otros creen que cuesta demasiado o que debe pagar una parte quien se beneficia.",
"Q036": "Un gran tenedor es quien posee muchas viviendas, y los fondos de inversión compran pisos para alquilarlos. Unos quieren limitar esas compras para frenar la especulación. Otros creen que esa inversión aumenta la oferta de alquiler y que limitarla daña el mercado.",
"Q037": "Para ir al psicólogo o al psiquiatra en la sanidad pública hay que esperar mucho. Unos quieren ampliar de forma importante esa atención con más profesionales. Otros creen que basta con gestionar mejor o prefieren dedicar el dinero a otros servicios.",
"Q038": "El sistema de dependencia da ayudas y servicios a personas mayores o con discapacidad. Unos quieren un sistema público de cuidados que cubra a toda la población. Otros prefieren que pesen más las familias y el sector privado, o ven que costaría demasiado.",
"Q039": "Desde 2023, la ley liga la subida anual de las pensiones al IPC, es decir, a la inflación. Unos quieren dejarlo asegurado por ley para que nunca pierdan poder de compra. Otros prefieren poder ajustar según lo que aguanten las cuentas de la Seguridad Social.",
"Q040": "Los permisos por nacimiento los paga la Seguridad Social y hoy duran 16 semanas para cada progenitor. Unos quieren alargarlos. Otros prefieren dejarlos como están por su coste o por cómo afectan a las empresas.",
"Q041": "Sería un pago del Estado a todas las familias con hijos, sin mirar lo que ganan. Unos quieren crearlo para apoyar la crianza y la natalidad. Otros prefieren ayudar solo a las familias con menos ingresos o hacerlo con rebajas de impuestos.",
"Q042": "El ingreso mínimo vital es una ayuda estatal que se creó en 2020 para hogares sin recursos suficientes. Parte de quienes tienen derecho no la cobran. Unos quieren reforzarlo para que llegue a todos. Otros ven que cuesta mucho o piden que se exija más buscar empleo.",
"Q043": "Hablamos de pensiones, servicios y apoyos para personas con discapacidad y sus familias. Unos quieren aumentarlos. Otros creen que el sistema actual basta o prefieren gastar en otras prioridades.",
"Q044": "Limitar los precios por ley es poner un tope a productos básicos como los alimentos. Unos lo quieren para frenar la subida de la cesta de la compra. Otros avisan de que topar precios puede dejar las estanterías vacías o reducir la oferta.",
"Q045": "Vender a pérdidas es vender por debajo de lo que cuesta producir. Las organizaciones agrarias denuncian que les pasa a agricultores y ganaderos. Unos quieren prohibirlo por ley. Otros creen que distorsiona el mercado y que habría que regularlo de otra manera.",
"Q046": "Desde 2023, los autónomos cotizan por tramos según lo que ganan de verdad. Unos quieren que la cuota se ajuste siempre a sus ingresos reales. Otros prefieren una cuota fija o poder elegir con qué base cotizan.",
"Q047": "El fraude fiscal es no pagar los impuestos que se deben, y Hacienda lo persigue con inspecciones. Unos quieren más inspectores y multas más duras. Otros creen que lo actual es suficiente o temen una presión excesiva sobre pymes y autónomos.",
"Q048": "En el mercado mayorista, el precio de la luz lo marca la tecnología más cara que hace falta en cada hora. Unos quieren intervenirlo, con topes, una empresa pública o un sistema de precios distinto, para que baje. Otros prefieren que lo fije el mercado.",
"Q049": "El turismo masivo genera quejas en algunas zonas por los precios, la falta de vivienda y la saturación. Unos quieren poner límites al número de visitantes. Otros defienden no limitarlo por lo que aporta a la economía y al empleo, y gestionarlo de otra manera.",
"Q050": "Recortar el gasto público es gastar menos para reducir el déficit y la deuda. Unos lo piden para sanear las cuentas. Otros avisan de que afecta a los servicios públicos y prefieren subir los ingresos antes que recortar.",
"Q051": "El paro es una ayuda que se cobra durante un tiempo limitado después de perder el empleo. Unos quieren que dure más y que sea mayor. Otros temen que así se busque trabajo con menos prisa o que cueste demasiado.",
"Q052": "Las cooperativas y la economía social son empresas gestionadas por sus trabajadores o por entidades sin ánimo de lucro. Unos quieren fomentarlas con ayudas públicas. Otros creen que no deben tener un trato distinto al de otras empresas.",
"Q053": "Se trata de reducir permisos, licencias y papeleo para abrir un negocio o hacer gestiones. Unos quieren simplificar para ganar agilidad. Otros recuerdan que algunas normas protegen el medio ambiente, a los trabajadores o a los consumidores.",
"Q054": "España se ha propuesto alcanzar la neutralidad climática en 2050, es decir, no emitir más de lo que se absorbe. Unos quieren adelantar esa fecha. Otros prefieren mantener el plazo o relajarlo por lo que cuesta a la industria, al empleo o a las familias.",
"Q055": "La desalación convierte agua de mar en agua potable. Las infraestructuras hidráulicas, como embalses, trasvases y canales, llevan agua adonde falta. Unos quieren ampliarlas para asegurar el abastecimiento. Otros avisan de su impacto ambiental y de su coste, y prefieren consumir menos.",
"Q056": "Se refiere a los toros y a otros espectáculos donde se usan animales. Unos quieren prohibirlos por el maltrato. Otros los defienden como tradición y patrimonio cultural, o prefieren que decida cada territorio.",
"Q057": "En un sistema de depósito, al comprar un envase se paga una pequeña cantidad y se recupera al devolverlo para reciclar. Unos quieren hacerlo obligatorio para reciclar más. Otros temen el coste para el comercio pequeño y para los consumidores, o prefieren otros sistemas.",
"Q058": "El Consejo General del Poder Judicial es el órgano de gobierno de los jueces, y sus vocales los elige hoy el Parlamento. Unos quieren que los elijan los propios jueces para reforzar su independencia. Otros prefieren que siga haciéndolo el Parlamento, porque representa a la ciudadanía.",
"Q059": "La corrupción política son delitos como la malversación o el cohecho cometidos por cargos públicos. Unos quieren penas más duras e inhabilitaciones más largas para los condenados. Otros creen que las penas actuales bastan y prefieren centrarse en prevenir y controlar.",
"Q060": "Hoy España es una monarquía parlamentaria. La Constitución de 1978 pone al Rey como jefe del Estado, y el cargo es hereditario. Unos quieren pasar a una república, con un jefe del Estado elegido. Otros prefieren mantener la monarquía por estabilidad o tradición, o no lo ven prioritario.",
"Q061": "El gasto en defensa paga a las Fuerzas Armadas y su material, y la OTAN pide a sus miembros que lo suban. Unos quieren aumentarlo por seguridad y por compromisos internacionales. Otros prefieren dedicar ese dinero a servicios sociales o rechazan el rearme.",
"Q062": "Cuando un país cede soberanía a la UE, ciertas decisiones se toman en común, como la moneda, el comercio o las normas del mercado. Unos quieren más integración europea, por ejemplo en política exterior, fiscal o de defensa. Otros prefieren decidir más a escala nacional.",
"Q063": "Se trata del tamaño del Gobierno y de la administración, es decir, de cuántos ministerios, altos cargos de libre designación y asesores hay. Unos quieren reducirlos para ahorrar y simplificar. Otros creen que las cifras actuales son necesarias y que el ahorro sería pequeño.",
"Q064": "El reconocimiento facial identifica a las personas por la cara con cámaras y algoritmos. Unos quieren prohibirlo en la calle por el riesgo para la privacidad y las libertades. Otros lo aceptarían con garantías, para la seguridad o para investigar delitos.",
"Q065": "Hoy lo habitual es vivir diez años en España para pedir la nacionalidad, y menos tiempo en algunos casos, como los países iberoamericanos. Unos quieren endurecer los requisitos con más años, exámenes o ausencia de antecedentes. Otros prefieren dejarlos como están o facilitarlos para favorecer la integración.",
"Q066": "La ley de 2004 creó medidas específicas, como juzgados, protección y ayudas, contra la violencia machista en la pareja. Unos quieren mantenerla. Otros prefieren sustituirla por una ley que proteja por igual a todas las víctimas de violencia doméstica.",
"Q067": "Desde 2023, la ley trans permite cambiar el sexo que figura en el registro civil con una simple declaración, con requisitos de edad. Unos quieren que siga siendo así. Otros prefieren exigir un informe médico o psicológico, o no permitirlo.",
"Q068": "La ley de memoria democrática, de 2022, regula el reconocimiento de las víctimas de la Guerra Civil y la dictadura, las exhumaciones y la retirada de símbolos. Unos quieren mantenerla. Otros quieren derogarla o cambiarla por una ley de concordia.",
"Q069": "La ley de seguridad ciudadana de 2015, a la que sus críticos llaman «ley mordaza», pone multas por cosas como desobedecer a un agente o manifestarse sin avisar. Unos quieren derogarla porque limita derechos. Otros prefieren mantenerla porque protege el orden público y a los agentes.",
"Q070": "La ley permite abortar en las primeras 14 semanas, y hasta las 22 en casos concretos. Unos quieren garantizar que se pueda hacer en la sanidad pública. Otros prefieren restringirlo o no pagarlo con dinero público.",
"Q071": "La ley de 2021 permite la eutanasia y el suicidio asistido a quien tiene una enfermedad grave e incurable o un sufrimiento insoportable y lo pide. Unos quieren mantenerla. Otros prefieren derogarla o limitarla y reforzar los cuidados paliativos.",
"Q072": "Hoy la edad mínima para dar permiso al uso de tus datos en redes sociales es de 14 años. Unos quieren prohibirlas a menores de 16 para protegerlos. Otros prefieren el control de los padres y la educación digital, sin prohibir.",
"Q073": "El Estado paga la clase de religión en la escuela, y la Iglesia católica y otras confesiones tienen exenciones fiscales y acuerdos propios. Unos quieren acabar con esa financiación, en nombre de un Estado laico. Otros prefieren mantenerla por tradición, por los acuerdos vigentes o por la labor social de la Iglesia.",
"Q074": "En algunas comunidades hay otra lengua oficial además del castellano, como el catalán, el gallego, el euskera o el valenciano, y la enseñanza se da en esa lengua. Unos quieren garantizar que el castellano sea lengua de enseñanza en toda España. Otros defienden el modelo que tiene cada comunidad.",
"Q075": "El deporte base es el que practican niños y jóvenes en colegios, clubes y municipios. Unos quieren más inversión pública. Otros creen que debería financiarse más con dinero privado o que no es una prioridad.",
"Q076": "La Constitución de 1978 habla de la unidad de España y no prevé un referéndum de autodeterminación. Unos quieren reconocer ese derecho a las comunidades que lo pidan. Otros se oponen porque rompería la unidad del Estado y la soberanía nacional.",
"Q077": "El sistema de financiación autonómica reparte el dinero entre comunidades según su población y otros factores, como el envejecimiento o la dispersión. Unos quieren reformarlo para reducir las diferencias de recursos por habitante entre comunidades. Otros prefieren tener en cuenta otros factores o mantener regímenes propios.",
"Q078": "La despoblación afecta a muchos pueblos pequeños del interior. Unos quieren dar incentivos fiscales y garantizar servicios como sanidad, escuela o internet para que la gente se quede. Otros lo ven caro o poco eficaz y prefieren impulsar la actividad económica.",
"Q079": "Gibraltar es un territorio británico en el sur de la península. España reclama su soberanía desde el Tratado de Utrecht de 1713. Unos quieren seguir reclamándola. Otros prefieren negociar fórmulas de cooperación o aceptar la situación actual.",
"Q080": "Euskadi, igual que Navarra, recauda casi todos sus impuestos y paga al Estado un «cupo» por los servicios que este presta. Es el régimen del concierto económico. Unos quieren reconocerlo y ampliarlo, junto con las competencias vascas. Otros lo consideran un privilegio y quieren el mismo trato para todas las comunidades.",
"Q081": "Catalunya tiene hoy el sistema de financiación común, y su Gobierno pide uno propio, con el que recaudar sus impuestos y pagar después al Estado. Unos quieren una hacienda propia con financiación singular. Otros creen que rompería la solidaridad con el resto de comunidades.",
"Q082": "Galicia ya tiene muchas competencias, pero reclama otras, como las costas, los puertos, el salvamento marítimo y las cuencas de los ríos. Unos quieren que se le transfieran. Otros creen que deben seguir en manos del Estado.",
"Q083": "Canarias tiene un régimen especial, el REF, con ventajas fiscales por su lejanía y su insularidad, y con ayudas al transporte entre las islas. Unos quieren reforzarlo. Otros creen que basta con el actual o no quieren ampliar los tratos diferenciados.",
"Q084": "Andalucía sostiene que ha recibido históricamente menos dinero por habitante del que le correspondía. Unos quieren que el Estado invierta más en Andalucía para corregir esa diferencia. Otros creen que debe resolverse con un sistema común para todas las comunidades.",
"Q085": "La Comunitat Valenciana sostiene que recibe menos financiación por habitante que la media y que de ahí viene buena parte de su deuda. Unos quieren reformar el sistema para corregirlo y condonar parte de la deuda. Otros creen que debe resolverse con un sistema común para todas las comunidades, o que la deuda hay que pagarla.",
"Q111": "En España hay tres tipos de IVA: el general del 21 %, el reducido del 10 % y el superreducido del 4 %. Los alimentos básicos pagan hoy los tipos bajos y el resto, más. Unos quieren bajar el IVA de la comida y de otros productos de primera necesidad para aliviar el gasto de los hogares. Otros temen que se pierda mucha recaudación y que la rebaja no llegue al precio final.",
"Q112": "Desde 2023 se aplicaron gravámenes temporales sobre los beneficios de los bancos y de las grandes energéticas. Unos quieren un impuesto extraordinario estable sobre esos beneficios para financiar servicios públicos. Otros creen que desanima la inversión y acaba pagándolo el cliente.",
"Q113": "Las grandes eléctricas, gasistas y petroleras son hoy empresas privadas, y muchas cotizan en bolsa. Unos quieren que pasen a control público, total o parcial, para controlar los precios y la política energética. Otros creen que el Estado es peor gestor y que basta con regularlas.",
"Q114": "El Estado tiene el ICO, que da créditos y avales a empresas, pero no un banco público que ofrezca cuentas y préstamos a toda la población. Unos quieren crearlo para dar crédito barato y no depender solo de la banca privada. Otros creen que la banca debe seguir en manos privadas.",
"Q115": "Desde 2019 las empresas deben registrar la jornada diaria de cada persona trabajadora. Las horas extra deberían pagarse o compensarse con descanso, pero hay horas que no se cobran. Unos quieren un registro digital obligatorio y más inspecciones. Otros temen más burocracia y costes para las pequeñas empresas.",
"Q116": "La edad legal de jubilación sube poco a poco hasta los 67 años en 2027, y se mantiene en 65 para quien ha cotizado 38 años y medio. Unos quieren reducirla, sobre todo en los trabajos más duros. Otros creen que, con una población cada vez más envejecida, no se puede pagar sin retrasarla o mantenerla.",
"Q117": "La UE ha negociado un acuerdo comercial con Mercosur, el bloque de Argentina, Brasil, Paraguay y Uruguay, para rebajar aranceles entre ambos lados. Unos quieren rechazarlo porque temen que perjudique al campo y a la industria europeos. Otros lo defienden porque abre mercados a las exportaciones y abarata productos.",
"Q118": "Hoy cada comunidad y cada ciudad fija sus propias tarifas de transporte público, con descuentos que el Estado cofinancia en parte. Unos quieren un abono único estatal a precio reducido para moverse por todo el país. Otros prefieren que lo decida cada territorio, o dudan de su coste.",
"Q119": "Los municipios de más de 50.000 habitantes deben tener zonas de bajas emisiones, donde se limita el acceso de los coches más contaminantes. Unos quieren eliminar esa obligación porque restringe la libertad de circulación y perjudica al comercio. Otros la defienden para mejorar el aire de las ciudades.",
"Q120": "Hoy el Gobierno propone al Fiscal General del Estado, el Rey lo nombra y lo cesa el Gobierno. Unos quieren que se elija sin esa dependencia, por ejemplo con mayoría del Congreso. Otros creen que el sistema actual es correcto y que la Fiscalía debe seguir la política criminal del Ejecutivo.",
"Q121": "El Tribunal Constitucional tiene 12 magistrados. El Congreso propone a cuatro, el Senado a cuatro, el Gobierno a dos y el Consejo General del Poder Judicial a dos. Unos quieren cambiar ese sistema para que los partidos influyan menos. Otros creen que el reparto actual refleja la voluntad de las Cortes y no hace falta reformarlo.",
"Q122": "Los escaños del Congreso se reparten por provincias con la regla D'Hondt. Eso favorece a los partidos más votados en cada provincia y hace que algunos votos pesen más que otros. Unos quieren una ley electoral más proporcional, para que cada voto valga lo mismo. Otros prefieren mantener el sistema actual, que da más estabilidad.",
"Q123": "Hoy se vota desde los 18 años. En otros países europeos, como Austria o Malta, ya se puede votar desde los 16. Unos quieren bajar la edad para dar voz a la juventud. Otros creen que a esa edad aún no hay madurez suficiente y piden dejarla en 18.",
"Q124": "La ley de amnistía de 2024 extinguió responsabilidades penales de personas vinculadas al procés catalán. El Tribunal Constitucional la ha avalado en lo esencial. Unos quieren derogarla porque creen que premia a quien incumplió la ley. Otros la defienden como una vía para cerrar el conflicto político.",
"Q125": "Los centros de internamiento de extranjeros retienen hasta 60 días a personas pendientes de expulsión, sin haber cometido un delito. Unos quieren cerrarlos porque creen que priva de libertad por una falta administrativa. Otros los consideran necesarios para poder ejecutar las expulsiones.",
"Q126": "Quien reside legalmente en España puede pedir que vengan su cónyuge e hijos menores, si cumple requisitos de ingresos y de vivienda. Unos quieren facilitarlo para que las familias no estén separadas. Otros prefieren endurecer las condiciones o limitarlo.",
"Q127": "España forma parte de la OTAN desde 1982, y en 1986 los españoles votaron en referéndum seguir dentro. Unos quieren salir porque ven la alianza como un instrumento de otros países y una fuente de gasto militar. Otros defienden quedarse porque da seguridad y peso internacional.",
"Q128": "En las bases de Rota, en Cádiz, y de Morón, en Sevilla, hay presencia militar de Estados Unidos por un convenio bilateral de defensa. Unos quieren cerrar las bases extranjeras para que España decida sola su política exterior. Otros defienden mantenerlas por la alianza y los puestos de trabajo.",
"Q129": "El Gobierno aprobó un embargo de armas a Israel por la guerra de Gaza. Unos quieren extenderlo a todo el material de doble uso, el que sirve para fines civiles y militares, y al tránsito por puertos y bases. Otros prefieren no ir más allá, o creen que no se deben cortar relaciones comerciales y de seguridad.",
"Q130": "Desde la invasión rusa de 2022, España ha enviado ayuda militar y financiera a Ucrania. Unos quieren seguir enviándola para frenar a Rusia y defender la seguridad europea. Otros piden dejar de hacerlo y buscar una salida diplomática al conflicto.",
"Q131": "El servicio militar obligatorio se suspendió en 2001 y el Ejército es hoy profesional y voluntario. Unos quieren restablecer algún tipo de servicio, obligatorio o voluntario y pagado, para los jóvenes. Otros creen que un ejército profesional es más eficaz y rechazan obligar a nadie.",
"Q132": "Las ratios fijan por ley el número máximo de alumnos por aula, hoy de 25 en Primaria y de 30 en la ESO. Unos quieren bajarlas para dar más atención a cada alumno, lo que exige más profesorado. Otros creen que cuesta mucho y que importa más la calidad de la enseñanza.",
"Q133": "La prueba para entrar en la universidad, la selectividad o PAU, la elabora cada comunidad autónoma, así que los exámenes y las notas pueden variar de un sitio a otro. Unos quieren una prueba única para toda España para que la nota se pueda comparar. Otros defienden que cada comunidad decida según su currículo.",
"Q134": "La caza se regula sobre todo por comunidades autónomas. Es una actividad muy arraigada en el medio rural, con un sector económico detrás. Unos quieren prohibir la caza de recreo por razones de bienestar animal. Otros la defienden como tradición y como herramienta para controlar especies y mantener el campo.",
"Q135": "En España la prostitución no es delito, pero tampoco está regulada como una actividad laboral. Sí lo es obligar a otra persona a ejercerla. Unos quieren prohibirla y sancionar a quien paga y a quien se lucra, por considerarla una forma de violencia. Otros piden regularla como trabajo, con derechos para quien la ejerce.",
"Q136": "La ley española declara nulo el contrato de gestación subrogada, el llamado vientre de alquiler. Sin embargo, algunas parejas lo contratan en el extranjero y piden inscribir a sus hijos aquí. Unos quieren prohibirlo del todo y perseguir esa intermediación. Otros prefieren regularlo con garantías y sin ánimo de lucro.",
"Q137": "España se organiza en 17 comunidades autónomas con parlamento y competencias propias, como la sanidad y la educación. Unos quieren suprimir ese modelo y devolver las competencias a un Estado central. Otros defienden el sistema autonómico como forma de acercar las decisiones a los ciudadanos.",
"Q138": "En Francia se prohibieron los vuelos nacionales cuando existe un tren que hace el mismo trayecto en menos de dos horas y media. En España no existe una norma así. Unos quieren prohibir los vuelos cortos con alternativa ferroviaria y los jets privados para reducir emisiones. Otros creen que limita la libertad de viajar y perjudica a la conectividad.",
"Q139": "Hoy, en las elecciones generales, se vota una lista cerrada y bloqueada de cada partido, sin poder cambiar el orden de los candidatos. Unos quieren listas abiertas para que cada votante elija a personas concretas. Otros creen que las listas cerradas dan más estabilidad a los partidos y al Parlamento.",
"Q140": "La Ley de Partidos de 2002 permite ilegalizar a los partidos que apoyen la violencia o vulneren los principios democráticos. Defender la independencia por vías pacíficas no es motivo de ilegalización. Unos quieren poder ilegalizar también a los partidos que la promuevan. Otros creen que eso limitaría la libertad de ideas.",
"Q141": "El delito de sedición, que castigaba el alzamiento público para impedir las leyes o el cumplimiento de las resoluciones judiciales, se eliminó en 2022. Hoy esas conductas se castigan con otros delitos, como los desórdenes públicos. Unos quieren volver a penalizarlo. Otros defienden la situación actual.",
"Q142": "España tiene relaciones diplomáticas con Israel y también con los países árabes de la zona. Por la guerra de Gaza, unos quieren romper esas relaciones para presionar al Gobierno israelí. Otros creen que es mejor mantener el diálogo y no cerrar los canales diplomáticos.",
"Q143": "Una renta básica universal es una cantidad de dinero que el Estado paga a toda persona, tenga o no empleo y sea cual sea su renta. Hoy existen ayudas solo para quien cumple unos requisitos, como el ingreso mínimo vital. Unos quieren implantarla para garantizar un mínimo a todo el mundo. Otros creen que costaría demasiado y desincentivaría el trabajo.",
"Q144": "Europa tiene desde 2024 un reglamento de inteligencia artificial que clasifica los usos según su riesgo, y España cuenta con una agencia propia, la AESIA, para vigilarlo. Unos quieren una ley que limite y supervise los usos de alto riesgo, como los algoritmos que deciden contrataciones o prestaciones. Otros creen que ya hay suficiente regulación y que más reglas frenarían la innovación.",
"Q145": "España tiene el supercomputador público MareNostrum 5, en Barcelona, pero buena parte de la tecnología de inteligencia artificial depende de grandes empresas extranjeras. Unos quieren que el Estado invierta en centros de cálculo y modelos propios para ganar soberanía digital. Otros creen que debe dejarse al sector privado y limitarse a apoyarlo.",
"Q146": "La inteligencia artificial se regula hoy con el reglamento europeo, que impone obligaciones sobre todo a los usos de más riesgo. Unos quieren reducir esas obligaciones para no frenar la innovación ni la inversión. Otros piden mantenerlas para proteger los derechos de las personas.",
"Q147": "Hoy hay deducciones fiscales para las empresas que invierten en investigación y tecnología. Unos quieren ampliarlas para que las empresas, sobre todo las pymes, adopten cuanto antes la inteligencia artificial. Otros creen que el dinero público no debe elegir qué tecnología se premia y prefieren bajar impuestos o quitar trabas a todas por igual.",
}
if len(sys.argv) > 1:
    qs = [l.split('|')[0] for l in open(sys.argv[1]).read().strip().split('\n')] + ['Q085']
    missing = [q for q in qs if q not in C]; extra = [q for q in C if q not in qs]
    assert not missing and not extra, (missing, extra)
bad = [q for q, t in C.items() if ';' in t]
assert not bad, ('punto y coma en', bad)
json.dump(C, open('docs/taxonomy/question_context.json', 'w'), ensure_ascii=False, indent=1)
print(len(C), 'contextos | longitud media', sum(len(v) for v in C.values()) // len(C), '| sin ";"')
